    /// <summary>
    /// Disconnects website from the current user's Telegram account
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> DisconnectWebsiteAsync(long websiteId = default)
    {

           using var activity =  StartCallActivity("DisconnectWebsiteAsync", typeof(DisconnectWebsite).FullName ?? "DisconnectWebsiteAsync");

           try
           {
             return client.DisconnectWebsiteAsync(websiteId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
